@@ -0,0 +1,21 @@
+import { Branch } from "../types";
+import { getSupabase, isSupabaseConfigured } from "./supabase";
+import seedBranches from "../../supabase/seed_branches.json";
+
+export async function loadBranches(): Promise<Branch[]> {
+  if (isSupabaseConfigured) {
+    try {
+      const supabase = getSupabase();
+      const { data, error } = await supabase
+        .from("branches")
+        .select("id, name, city")
+        .order("id");
+      if (!error && data && data.length > 0) {
+        return data as Branch[];
+      }
+    } catch {
+      // Fall through to seed
+    }
+  }
+  return seedBranches as Branch[];
+}
diff --git a/app/lib/closings.ts b/app/lib/closings.ts
new file mode 100644
--- /dev/null
+++ b/app/lib/closings.ts
@@ -0,0 +1,148 @@
+import { DailyClosing, FinancialFields } from "../types";
+import { getSupabase, isSupabaseConfigured } from "./supabase";
+
+export interface ClosingInput {
+  branchId: string;
+  businessDate: string;
+  reviewedData?: Partial<FinancialFields>;
+  manualActualCash?: number;
+  zReportImageUrl?: string;
+  paymentProofImageUrls?: string[];
+}
+
+async function tryUploadImage(
+  dataUrl: string,
+  closingId: string,
+  index: number,
+): Promise<string> {
+  if (isSupabaseConfigured) {
+    try {
+      const supabase = getSupabase();
+      const resp = await fetch(dataUrl);
+      const blob = await resp.blob();
+      const path = `${closingId}/${index}_${Date.now()}.jpg`;
+      const { error } = await supabase.storage
+        .from("closing-images")
+        .upload(path, blob, { contentType: blob.type });
+      if (!error) {
+        const { data } = supabase.storage
+          .from("closing-images")
+          .getPublicUrl(path);
+        return data.publicUrl;
+      }
+    } catch {
+      // Fall through
+    }
+  }
+  // TODO: upload to Supabase Storage when configured; data URL stored for now
+  return dataUrl;
+}
+
+export async function checkDuplicateClosing(
+  branchId: string,
+  businessDate: string,
+): Promise<boolean> {
+  if (isSupabaseConfigured) {
+    try {
+      const supabase = getSupabase();
+      const { data } = await supabase
+        .from("daily_closings")
+        .select("id")
+        .eq("branch_id", branchId)
+        .eq("business_date", businessDate)
+        .maybeSingle();
+      return Boolean(data);
+    } catch {
+      // Fall through to localStorage
+    }
+  }
+  if (typeof window !== "undefined") {
+    const key = `closing_${branchId}_${businessDate}`;
+    return Boolean(localStorage.getItem(key));
+  }
+  return false;
+}
+
+export async function saveClosing(
+  input: ClosingInput,
+): Promise<DailyClosing> {
+  const now = new Date().toISOString();
+  const timestamp = Date.now().toString();
+  const id = `close-${timestamp}`;
+
+  // Upload images if Supabase Storage is configured
+  let zReportUrl = input.zReportImageUrl;
+  let proofUrls = input.paymentProofImageUrls;
+
+  if (zReportUrl) {
+    zReportUrl = await tryUploadImage(zReportUrl, id, 0);
+  }
+  if (proofUrls && proofUrls.length > 0) {
+    proofUrls = await Promise.all(
+      proofUrls.map((url, i) => tryUploadImage(url, id, i + 1)),
+    );
+  }
+
+  const closing: DailyClosing = {
+    id,
+    branchId: input.branchId,
+    businessDate: input.businessDate,
+    status: "pending",
+    zReportImageUrl: zReportUrl,
+    paymentProofImageUrls: proofUrls,
+    reviewedData: input.reviewedData,
+    manualActualCash: input.manualActualCash,
+    createdAt: now,
+    updatedAt: now,
+  };
+
+  if (isSupabaseConfigured) {
+    try {
+      const supabase = getSupabase();
+      const row = {
+        id: closing.id,
+        branch_id: closing.branchId,
+        business_date: closing.businessDate,
+        status: closing.status,
+        z_report_image_url: closing.zReportImageUrl ?? null,
+        payment_proof_image_urls: closing.paymentProofImageUrls ?? null,
+        reviewed_data: closing.reviewedData ?? null,
+        manual_actual_cash: closing.manualActualCash ?? null,
+        created_at: closing.createdAt,
+        updated_at: closing.updatedAt,
+      };
+      const { data, error } = await supabase
+        .from("daily_closings")
+        .insert(row)
+        .select()
+        .single();
+      if (!error && data) {
+        return mapRowToClosing(data);
+      }
+    } catch {
+      // Fall through to local storage
+    }
+  }
+
+  if (typeof window !== "undefined") {
+    const key = `closing_${input.branchId}_${input.businessDate}`;
+    localStorage.setItem(key, JSON.stringify(closing));
+  }
+
+  return closing;
+}
+
+function mapRowToClosing(row: Record<string, unknown>): DailyClosing {
+  return {
+    id: row.id as string,
+    branchId: row.branch_id as string,
+    businessDate: row.business_date as string,
+    status: row.status as DailyClosing["status"],
+    zReportImageUrl: row.z_report_image_url as string | undefined,
+    paymentProofImageUrls: row.payment_proof_image_urls as string[] | undefined,
+    reviewedData: row.reviewed_data as Partial<FinancialFields> | undefined,
+    manualActualCash: row.manual_actual_cash as number | undefined,
+    createdAt: row.created_at as string,
+    updatedAt: row.updated_at as string,
+  };
+}
