// app/lib/closings.ts
import { DailyClosing, FinancialFields } from "../types";
import { getSupabase, isSupabaseConfigured } from "./supabase";

export interface ClosingInput {
  branchId: string;
  businessDate: string;
  zReportImageUrl?: string;
  paymentProofImageUrls?: string[];
  reviewedData?: Partial<FinancialFields>;
  manualActualCash?: number;
}

export async function checkDuplicateClosing(
  branchId: string,
  businessDate: string,
): Promise<boolean> {
  if (isSupabaseConfigured) {
    try {
      const supabase = getSupabase();
      const { data } = await supabase
        .from("daily_closings")
        .select("id")
        .eq("branch_id", branchId)
        .eq("business_date", businessDate)
        .maybeSingle();
      return Boolean(data);
    } catch {
      // fall through to localStorage
    }
  }
  // localStorage fallback
  if (typeof window !== "undefined") {
    const key = `closing_${branchId}_${businessDate}`;
    return Boolean(localStorage.getItem(key));
  }
  return false;
}

export async function saveClosing(
  input: ClosingInput,
): Promise<DailyClosing> {
  const now = new Date().toISOString();
  const timestamp = Date.now().toString();
  const id = `close-${timestamp}`;

  const closing: DailyClosing = {
    id,
    branchId: input.branchId,
    businessDate: input.businessDate,
    status: "pending",
    zReportImageUrl: input.zReportImageUrl,
    paymentProofImageUrls: input.paymentProofImageUrls,
    reviewedData: input.reviewedData,
    manualActualCash: input.manualActualCash,
    createdAt: now,
    updatedAt: now,
  };

  if (isSupabaseConfigured) {
    try {
      const supabase = getSupabase();
      const { data, error } = await supabase
        .from("daily_closings")
        .insert({
          id: closing.id,
          branch_id: closing.branchId,
          business_date: closing.businessDate,
          status: closing.status,
          z_report_image_url: closing.zReportImageUrl,
          payment_proof_image_urls: closing.paymentProofImageUrls,
          reviewed_data: closing.reviewedData,
          manual_actual_cash: closing.manualActualCash,
          created_at: closing.createdAt,
          updated_at: closing.updatedAt,
        })
        .select()
        .single();
      if (!error && data) {
        return mapRowToClosing(data);
      }
    } catch (e) {
      console.warn("Supabase save failed, queueing locally", e);
    }
  }

  // Local fallback
  if (typeof window !== "undefined") {
    const key = `closing_${input.branchId}_${input.businessDate}`;
    localStorage.setItem(key, JSON.stringify(closing));
  }

  return closing;
}

function mapRowToClosing(row: any): DailyClosing {
  return {
    id: row.id,
    branchId: row.branch_id,
    businessDate: row.business_date,
    status: row.status,
    zReportImageUrl: row.z_report_image_url,
    paymentProofImageUrls: row.payment_proof_image_urls,
    reviewedData: row.reviewed_data,
    manualActualCash: row.manual_actual_cash,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}
