"use client";

import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { ArrowRight, Calculator, Lock, Check, AlertCircle, Image as ImageIcon } from "lucide-react";
import { Branch, FinancialFields, EMPTY_FINANCIAL_FIELDS, computeShortageOrExcess } from "../types";
import { loadBranches } from "../lib/branches";
import { checkDuplicateClosing, saveClosing } from "../lib/closings";

type Step = 1 | 2 | 3;

interface ClosingResult {
  id: string;
  status: string;
}

export default function CashierPage() {
  const [step, setStep] = useState<Step>(1);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [branchesLoading, setBranchesLoading] = useState(true);
  const [branchesError, setBranchesError] = useState<string | null>(null);

  const [selectedBranch, setSelectedBranch] = useState<Branch | null>(null);
  const [isBranchLocked, setIsBranchLocked] = useState(false);

  const [businessDate, setBusinessDate] = useState(
    new Date().toISOString().split("T")[0],
  );

  const [fields, setFields] = useState<FinancialFields>({ ...EMPTY_FINANCIAL_FIELDS });
  const [manualActualCash, setManualActualCash] = useState<string>("");
  const [manualActualCashEnabled, setManualActualCashEnabled] = useState(false);

  const [zReportImage, setZReportImage] = useState<string | null>(null);
  const [proofImages, setProofImages] = useState<string[]>([]);

  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [closingResult, setClosingResult] = useState<ClosingResult | null>(null);

  // Load branches via useEffect
  useEffect(() => {
    let cancelled = false;
    (async () => {
      setBranchesLoading(true);
      try {
        const result = await loadBranches();
        if (!cancelled) {
          setBranches(result);
          setBranchesError(null);
        }
      } catch (e) {
        if (!cancelled) {
          setBranchesError("تعذّر تحميل قائمة الفروع");
        }
      } finally {
        if (!cancelled) setBranchesLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  // Compute shortage/excess whenever relevant fields change
  const actualCash = manualActualCashEnabled && manualActualCash !== ""
    ? parseFloat(manualActualCash) || 0
    : fields.cashActualHanded;

  useEffect(() => {
    setFields((prev) => ({
      ...prev,
      shortageOrExcess: computeShortageOrExcess(actualCash, prev.cashSystem),
    }));
  }, [actualCash, fields.cashSystem]);

  const handlePickBranch = (branch: Branch) => {
    setSelectedBranch(branch);
    setIsBranchLocked(true);
  };

  const handleUnlockBranch = () => {
    if (window.confirm("تغيير الفرع؟ سيتم فقدان البيانات المدخلة.")) {
      setSelectedBranch(null);
      setIsBranchLocked(false);
      setStep(1);
      setFields({ ...EMPTY_FINANCIAL_FIELDS });
      setManualActualCash("");
      setManualActualCashEnabled(false);
      setZReportImage(null);
      setProofImages([]);
    }
  };

  const handleNumericChange = (
    key: keyof FinancialFields,
    value: string,
  ) => {
    if (value === "") {
      setFields((prev) => ({ ...prev, [key]: 0 }));
    } else {
      const num = parseFloat(value);
      setFields((prev) => ({ ...prev, [key]: Number.isFinite(num) ? num : prev[key] }));
    }
  };

  const numericDisplay = (val: number) => (val === 0 ? "" : String(val));

  const handleZReportUpload = (file: File | undefined) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      setZReportImage(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleProofUpload = (files: FileList | null) => {
    if (!files) return;
    Array.from(files).forEach((file) => {
      const reader = new FileReader();
      reader.onload = () => {
        setProofImages((prev) => [...prev, reader.result as string]);
      };
      reader.readAsDataURL(file);
    });
  };

  const canProceedToStep2 = selectedBranch !== null && businessDate !== "";

  const handleSave = useCallback(async () => {
    if (!selectedBranch) return;
    setSaving(true);
    setSaveError(null);
    try {
      const isDup = await checkDuplicateClosing(selectedBranch.id, businessDate);
      if (isDup) {
        const confirmed = window.confirm(
          "يوجد إقفال لهذا الفرع في هذا التاريخ. هل تريد المتابعة؟",
        );
        if (!confirmed) {
          setSaving(false);
          return;
        }
      }

      const input = {
        branchId: selectedBranch.id,
        businessDate,
        reviewedData: { ...fields },
        manualActualCash:
          manualActualCashEnabled && manualActualCash !== ""
            ? parseFloat(manualActualCash)
            : undefined,
        zReportImageUrl: zReportImage ?? undefined,
        paymentProofImageUrls: proofImages.length > 0 ? proofImages : undefined,
      };

      const result = await saveClosing(input);
      setClosingResult({
        id: result.id,
        status: "بانتظار اعتماد الإدارة المالية",
      });
      setStep(3);
    } catch (e: any) {
      setSaveError(e?.message ?? "حدث خطأ أثناء الحفظ");
    } finally {
      setSaving(false);
    }
  }, [selectedBranch, businessDate, fields, manualActualCash, manualActualCashEnabled, zReportImage, proofImages]);

  // ---- Render ----

  return (
    <main className="mx-auto max-w-3xl px-4 py-10" dir="rtl">
      <Link
        href="/"
        className="mb-6 inline-flex items-center gap-1 text-sm text-slate-600 hover:text-slate-900"
      >
        <ArrowRight className="h-4 w-4" />
        العودة للرئيسية
      </Link>

      <div className="card-frame p-6">
        {/* Header */}
        <div className="mb-6 flex items-center gap-3">
          <Calculator className="h-8 w-8 text-emerald-600" />
          <h1 className="text-2xl font-bold">شاشة الكاشير</h1>
        </div>

        {/* Progress indicator */}
        <div className="mb-6 flex items-center justify-center gap-2">
          {[1, 2, 3].map((s) => (
            <div
              key={s}
              className={`flex h-8 w-8 items-center justify-center rounded-full text-sm font-bold ${
                step >= s
                  ? "bg-emerald-600 text-white"
                  : "bg-slate-200 text-slate-500"
              }`}
            >
              {s}
            </div>
          ))}
        </div>

        {/* Step 1: Branch + Date + Images */}
        {step === 1 && (
          <div className="space-y-5">
            <h2 className="text-lg font-semibold">الخطوة 1: اختيار الفرع والتاريخ</h2>

            {/* Branch selector */}
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700">
                الفرع
              </label>
              {branchesLoading ? (
                <p className="text-sm text-slate-500">جارٍ تحميل الفروع…</p>
              ) : branchesError ? (
                <p className="text-sm text-red-600">{branchesError}</p>
              ) : !isBranchLocked ? (
                <select
                  className="input-base w-full"
                  value={selectedBranch?.id ?? ""}
                  onChange={(e) => {
                    const b = branches.find((x) => x.id === e.target.value);
                    if (b) handlePickBranch(b);
                  }}
                >
                  <option value="">— اختر الفرع —</option>
                  {branches.map((b) => (
                    <option key={b.id} value={b.id}>
                      {b.id} — {b.name}
                    </option>
                  ))}
                </select>
              ) : (
                <div className="flex items-center gap-2 rounded-md bg-slate-100 px-3 py-2">
                  <Lock className="h-4 w-4 text-slate-500" />
                  <span className="text-sm font-medium">
                    {selectedBranch?.id} — {selectedBranch?.name}
                  </span>
                  <button
                    type="button"
                    onClick={handleUnlockBranch}
                    className="mr-auto text-xs text-emerald-600 hover:underline"
                  >
                    تغيير الفرع
                  </button>
                </div>
              )}
            </div>

            {/* Business date */}
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700">
                تاريخ العمل
              </label>
              <input
                type="date"
                className="input-base w-full"
                value={businessDate}
                onChange={(e) => setBusinessDate(e.target.value)}
              />
            </div>

            {/* Z-Report image */}
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700">
                صورة تقرير Z (اختياري)
              </label>
              <input
                type="file"
                accept="image/*"
                onChange={(e) => handleZReportUpload(e.target.files?.[0])}
                className="block w-full text-sm"
              />
              {zReportImage && (
                <img
                  src={zReportImage}
                  alt="Z-Report"
                  className="mt-2 max-h-48 rounded border"
                />
              )}
            </div>

            {/* Payment proof images */}
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700">
                صور إثبات الدفع (اختياري)
